<?php
if (! defined('ABSPATH')) { exit; }
if (! current_user_can('pms_manage_crm')) { wp_die(__('You do not have permission to view this page.', 'pms')); }
$tab = sanitize_key(wp_unslash($_GET['tab'] ?? 'overview'));
$tabs = ['overview','leads','prospects','customers','pipeline','deals','activities','reports'];
if (! in_array($tab, $tabs, true)) { $tab = 'overview'; }
$notice = ''; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['pms_crm_action'])) {
    check_admin_referer('pms_crm_manage', 'pms_crm_nonce');
    $action = sanitize_key(wp_unslash($_POST['pms_crm_action']));
    if ($action === 'save_lead' || $action === 'save_prospect') {
        $type = $action === 'save_lead' ? 'lead' : 'prospect';
        $data = ['first_name'=>sanitize_text_field(wp_unslash($_POST['first_name']??'')),'last_name'=>sanitize_text_field(wp_unslash($_POST['last_name']??'')),'company'=>sanitize_text_field(wp_unslash($_POST['company']??'')),'email'=>sanitize_email(wp_unslash($_POST['email']??'')),'phone'=>sanitize_text_field(wp_unslash($_POST['phone']??'')),'source'=>sanitize_text_field(wp_unslash($_POST['source']??'')),'status'=>sanitize_key(wp_unslash($_POST['status']??'new')),'assigned_to'=>absint($_POST['assigned_to']??0),'notes'=>sanitize_textarea_field(wp_unslash($_POST['notes']??''))];
        if ($data['first_name'] === '') { $error = __('First name is required.', 'pms'); } else { PMS_CRM::save($type,$data); $notice = __('CRM record created.', 'pms'); }
        $tab = $type === 'lead' ? 'leads' : 'prospects';
    } elseif ($action === 'convert_lead') {
        $new = PMS_CRM::convert_lead(absint($_POST['id']??0)); $notice = $new ? __('Lead converted to prospect.', 'pms') : __('Lead could not be converted.', 'pms'); $tab='leads';
    } elseif ($action === 'save_customer') {
        $data=['prospect_id'=>absint($_POST['prospect_id']??0),'name'=>sanitize_text_field(wp_unslash($_POST['name']??'')),'company'=>sanitize_text_field(wp_unslash($_POST['company']??'')),'email'=>sanitize_email(wp_unslash($_POST['email']??'')),'phone'=>sanitize_text_field(wp_unslash($_POST['phone']??'')),'status'=>sanitize_key(wp_unslash($_POST['status']??'active')),'assigned_to'=>absint($_POST['assigned_to']??0),'notes'=>sanitize_textarea_field(wp_unslash($_POST['notes']??''))];
        if ($data['name']==='') { $error=__('Customer name is required.','pms'); } else { PMS_CRM::save('customer',$data); $notice=__('Customer created.','pms'); } $tab='customers';
    } elseif ($action === 'save_stage') {
        global $wpdb; $name=sanitize_text_field(wp_unslash($_POST['name']??'')); if($name!=='') {$wpdb->insert(PMS_CRM::stages_table(),['name'=>$name,'sort_order'=>absint($_POST['sort_order']??0),'probability'=>min(100,max(0,(float)($_POST['probability']??0))),'status'=>'active']); $notice=__('Pipeline stage added.','pms');} $tab='pipeline';
    } elseif ($action === 'save_deal') {
        $data=['title'=>sanitize_text_field(wp_unslash($_POST['title']??'')),'customer_id'=>absint($_POST['customer_id']??0),'prospect_id'=>absint($_POST['prospect_id']??0),'stage_id'=>absint($_POST['stage_id']??0),'amount'=>(float)($_POST['amount']??0),'currency'=>sanitize_text_field(wp_unslash($_POST['currency']??'')),'expected_close'=>sanitize_text_field(wp_unslash($_POST['expected_close']??'')),'assigned_to'=>absint($_POST['assigned_to']??0),'status'=>sanitize_key(wp_unslash($_POST['status']??'open')),'notes'=>sanitize_textarea_field(wp_unslash($_POST['notes']??''))];
        if($data['title']===''||!$data['stage_id']||$data['currency']===''){ $error=__('Deal title, stage and currency are required.','pms'); } else { PMS_CRM::save('deal',$data); $notice=__('Deal created.','pms'); } $tab='deals';
    } elseif ($action === 'save_activity') {
        $data=['subject'=>sanitize_text_field(wp_unslash($_POST['subject']??'')),'type'=>sanitize_key(wp_unslash($_POST['type']??'follow_up')),'due_at'=>sanitize_text_field(wp_unslash($_POST['due_at']??'')),'completed_at'=>!empty($_POST['completed'])?current_time('mysql'):null,'assigned_to'=>absint($_POST['assigned_to']??0),'lead_id'=>absint($_POST['lead_id']??0),'prospect_id'=>absint($_POST['prospect_id']??0),'customer_id'=>absint($_POST['customer_id']??0),'deal_id'=>absint($_POST['deal_id']??0),'notes'=>sanitize_textarea_field(wp_unslash($_POST['notes']??''))];
        if($data['subject']===''){ $error=__('Activity subject is required.','pms'); } else { PMS_CRM::save('activity',$data); $notice=__('Activity created.','pms'); } $tab='activities';
    }
}
$people=PMS_CRM::people(); $leads=PMS_CRM::leads(); $prospects=PMS_CRM::prospects(); $customers=PMS_CRM::customers(); $stages=PMS_CRM::stages(); $deals=PMS_CRM::deals(); $activities=PMS_CRM::activities(); $report=PMS_CRM::report();
include PMS_PLUGIN_DIR.'admin/views/partials/header.php';
?>
