<?php if($notice): ?><div class="pms-notice pms-notice-success"><?php echo esc_html($notice); ?></div><?php endif; ?><?php if($error): ?><div class="pms-notice pms-notice-error"><?php echo esc_html($error); ?></div><?php endif; ?>
<nav class="pms-payroll-tabs pms-crm-tabs" aria-label="CRM sections"><?php foreach(['overview'=>'Overview','leads'=>'Leads','prospects'=>'Prospects','customers'=>'Customers','pipeline'=>'Sales Funnel / Pipeline','deals'=>'Deals','activities'=>'Activities / Follow-ups','reports'=>'Sales Reports'] as $slug=>$label): ?><a class="<?php echo $tab===$slug?'is-active':''; ?>" href="<?php echo esc_url(admin_url('admin.php?page=pms-crm&tab='.$slug)); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
