le class="pms-table"><thead><tr><th>Name</th><th>Company</th><th>Contact</th><th>Status</th><th>Assigned</th><?php if($lead): ?><th>Source</th><th></th><?php endif; ?></tr></thead><tbody><?php foreach($items as $row): ?><tr><td><strong><?php echo esc_html(trim($row->first_name.' '.$row->last_name)); ?></strong></td><td><?php echo esc_html($row->company?:'—'); ?></td><td><?php echo esc_html($row->email?:($row->phone?:'—')); ?></td><td><?php echo esc_html(ucwords(str_replace('_',' ',$row->status))); ?></td><td><?php echo esc_html($row->assignee_name?:'—'); ?></td><?php if($lead): ?><td><?php echo esc_html($row->source?:'—'); ?></td><td><form method="post" class="pms-inline-form"><?php wp_nonce_field('pms_crm_manage','pms_crm_nonce'); ?><input type="hidden" name="pms_crm_action" value="convert_lead"><input type="hidden" name="id" value="<?php echo esc_attr($row->id); ?>"><button class="pms-btn-secondary pms-btn-small" type="submit">Convert</button></form></td><?php endif; ?></tr><?php endforeach; if(empty($items)): ?><tr><td colspan="7" class="pms-empty">No records yet.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?>
<?php if($tab==='customers'): ?><div class="pms-panel pms-form-panel"><div class="pms-section-head"><div><h2>Add Customer</h2></div></div><form method="post"><?php wp_nonce_field('pms_crm_manage','pms_crm_nonce'); ?><input type="hidden" name="pms_crm_action" value="save_customer"><div class="pms-form-grid"><div class="pms-form-row"><label>Name</label><input class="pms-input" name="name" required></div><div class="pms-form-row"><label>Company</label><input class="pms-input" name="company"></div><div class="pms-form-row"><label>Email</label><input class="pms-input" type="email" name="email"></div><div class="pms-form-row"><label>Phone</label><input class="pms-input" name="phone"></div><div class="pms-form-row"><label>Assigned to</label><select class="pms-input" name="assigned_to"><option value="">Unassigned</option><?php foreach($people as $person): ?><option value="<?php echo esc_attr($person->ID); ?>"><?php echo esc_html($person->display_name); ?></option><?php endforeach; ?></select></div></div><button class="pms-btn-primary" type="submit">Save customer</button></form></div><div class="pms-panel"><table class="pms-table"><thead><tr><th>Name</th><th>Company</th><th>Contact</th><th>Status</th><th>Assigned</th></tr></thead><tbody><?php foreach($customers as $row): ?><tr><td><strong><?php echo esc_html($row->name); ?></strong></td><td><?php echo esc_html($row->company?:'—'); ?></td><td><?php echo esc_html($row->email?:($row->phone?:'—')); ?></td><td><?php echo esc_html(ucfirst($row->status)); ?></td><td><?php echo esc_html($row->assignee_name?:'—'); ?></td></tr><?php endforeach; if(empty($customers)): ?><tr><td colspan="5" class="pms-empty">No customers yet.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?>
